// Attributs AFFICHÉS que le dictionnaire traduit : infobulle, texte d'attente, nom accessible, et le libellé
// d'un groupe d'options (`<optgroup label>`). Un attribut `value` n'est jamais touché (c'est une donnée).
const I18N_ATTRS = ['placeholder', 'title', 'aria-label', 'label'];
const I18N_ATTRS_SEL = I18N_ATTRS.map(a => '[' + a + ']').join(',');
function i18nWalk(root) {
  if (LANG !== 'en' || !root) return;
  // `querySelectorAll` ne rend que les DESCENDANTS : un nœud ajouté qui porte lui-même un `title` (bouton
  // de barre d'actions, champ de formulaire) est traduit aussi, sinon son infobulle resterait en français.
  const porteurs = root.querySelectorAll ? [...root.querySelectorAll(I18N_ATTRS_SEL)] : [];
  if (root.nodeType === 1 && root.matches && root.matches(I18N_ATTRS_SEL)) porteurs.unshift(root);
  // Une entrée identité (« Dashboards » -> « Dashboards ») ne réécrit rien : réécrire la même valeur
  // produirait une mutation de plus pour un observateur d'attributs ou de texte, sans fin.
  porteurs.forEach(el => {
    I18N_ATTRS.forEach(a => { const v = el.getAttribute(a); const en = v && I18N_EN[v.trim()]; if (en && en !== v.trim()) el.setAttribute(a, en); });
  });
  const w = document.createTreeWalker(root.nodeType === 3 ? root.parentNode || root : root, NodeFilter.SHOW_TEXT, null);
  const nodes = []; let n; while ((n = w.nextNode())) nodes.push(n);
  nodes.forEach(t => { const k = t.nodeValue.trim(); const en = k && I18N_EN[k]; if (en && en !== k) t.nodeValue = t.nodeValue.replace(k, en); });
}

export { i18nWalk };
